  catalog.before(section);
  const cls=section.querySelector('#topic-class'),subject=section.querySelector('#topic-subject'),topic=section.querySelector('#topic-name'),count=section.querySelector('#topic-count');
  const fill=(field,values,preferred,label=x=>x)=>{field.innerHTML=values.map(value=>`<option value="${e(value)}">${e(label(value))}</option>`).join('');field.value=values.includes(preferred)?preferred:values[0]||'';return field.value};
  const sync=()=>{topicPick.class=fill(cls,[...new Set(topicBank.map(topicClass))].sort(),topicPick.class);topicPick.subject=fill(subject,[...new Set(topicBank.filter(q=>topicClass(q)===topicPick.class).map(topicSubject))].sort(),topicPick.subject,subjectLabel);topicPick.topic=fill(topic,[...new Set(topicBank.filter(q=>topicClass(q)===topicPick.class&&topicSubject(q)===topicPick.subject).map(topicName))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true})),topicPick.topic,topicLabel);const list=topicQuestions(),years=[...new Set(list.map(pyqYear))].sort();count.textContent=`${list.length} ${t('questions')}${years.length?` · ${say('PYQ years','प्रश्नपत्र वर्ष')}: ${years.join(', ')}`:''}`;section.querySelector('#choose-topic').disabled=!list.length;section.querySelector('#topic-share-link').href=topicShareUrl();section.querySelector('#copy-topic-link').disabled=!list.length};
  cls.onchange=()=>{topicPick.class=cls.value;topicPick.subject='';topicPick.topic='';sync()};subject.onchange=()=>{topicPick.subject=subject.value;topicPick.topic='';sync()};topic.onchange=()=>{topicPick.topic=topic.value;sync()};sync();
  section.querySelector('#copy-topic-link').onclick=event=>copyShare(event.currentTarget,topicShareUrl());
  section.querySelector('#choose-topic').onclick=()=>{const list=topicQuestions(),iitm=topicPick.class===iitmClass,programme=iitm?iitmClass:`Class ${topicPick.class}`,title=`${programme} · ${topicPick.subject} · ${topicPick.topic} · PYQ`,titleHi=`${iitm?iitmClass:`कक्षा ${topicPick.class}`} · ${subjectLabel(topicPick.subject)} · ${topicLabel(topicPick.topic)} · पिछले प्रश्न`,ids=list.map(q=>q.qid);if(homeMode==='practice'){setupChoice(null,{title,hi:titleHi,subject:topicPick.subject,topic:topicPick.topic,ids});return}const marks=list.reduce((n,q)=>n+q.marks,0),original=iitm?examSets.find(x=>x.id==='IITM-ES-QPQ1-20230806'):null,exam={id:`SL-TOPIC-PYQ-${topicPick.class}-${topicPick.subject}-${topicPick.topic}`,title,titleHi,class:topicPick.class,subject:topicPick.subject,topic:topicPick.topic,durationMinutes:Math.max(15,Math.ceil(marks*1.5)),totalMarks:marks,questionIds:ids,info:{programme,assessment:`${topicPick.subject} topic wise PYQ`,date:[...new Set(list.map(pyqYear))].sort().join(', '),sourceNote:iitm?original.info.sourceNote:say('Previous year questions for this topic. Written scores are provisional and need teacher review.','इस विषय के पिछले वर्षों के प्रश्न। लिखित उत्तरों के अंक अस्थायी हैं और शिक्षक की जाँच आवश्यक है।'),verification:iitm?original.info.verification:[]}};setupChoice(exam)};
