 function clock(){clearInterval(clockId);tick();clockId=setInterval(tick,1000)}function tick(){if(!s||s.done)return;if(!s.deadline){timer.textContent=t('untimed');return}let n=Math.max(0,Math.ceil((s.deadline-Date.now())/1000));timer.textContent=Math.floor(n/60)+':'+String(n%60).padStart(2,'0');if(!n)finish()}
