 function objectiveScore(q,answer){if(!answered(q))return 0;if(q.type==='msq')return [...String(answer)].sort().join('')===[...q.correct].sort().join('')?q.marks:0;if(q.type==='fill')return (q.acceptedAnswers||[q.correct]).some(value=>gradeNorm(value)===gradeNorm(answer))?q.marks:0;if(q.type==='match'){const actual=String(answer).split('|');return q.correct.reduce((sum,letter,i)=>sum+(actual[i]===letter?q.marks/q.correct.length:0),0)}return answer===q.correct?q.marks:0}
