 function installPracticeCertificate(){if(!s?.done||s.mode!=='practice'||!s.practiceSetId||document.querySelector('#certificate-panel'))return;const set=practiceSets.find(item=>item.id===s.practiceSetId),first=document.querySelector('.card'),summary=document.querySelector('#provisional-summary');if(!set||!first||!summary)return;const scores=scoreSummary(qs()),eligible=certificateEligible(scores),percent=(scores.total/scores.totalMax*100).toFixed(1),panel=document.createElement('section');panel.id='certificate-panel';panel.className='certificate-panel';panel.innerHTML=`<h2>${say('Certificate of Completion','पूर्णता प्रमाणपत्र')}</h2><p>${say('Score','अंक')}: <strong>${scores.total}/${scores.totalMax} ${say('marks','अंक')} (${percent}%)</strong>. ${eligible?say('You can download a PDF certificate.','आप पीडीएफ प्रमाणपत्र डाउनलोड कर सकते हैं।'):say('A score of at least 60% is needed for a certificate.','प्रमाणपत्र के लिए कम से कम 60% अंक आवश्यक हैं।')}</p>${eligible?`<div class="certificate-details"><label>${say('Name on certificate','प्रमाणपत्र पर नाम')}<input id="certificate-name" maxlength="80" required value="${e(['Learner','विद्यार्थी'].includes(s.name)?'':s.name)}"></label><label>${say('Student ID (optional)','विद्यार्थी आईडी (वैकल्पिक)')}<input id="certificate-student-id" maxlength="100" value="${e(s.studentId||'')}"></label></div><button type="button" id="download-certificate">${say('Download Certificate of Completion (PDF)','पूर्णता प्रमाणपत्र पीडीएफ डाउनलोड करें')}</button><p id="certificate-status" role="status" aria-live="polite"></p>`:''}`;summary.after(panel);const button=panel.querySelector('#download-certificate');if(button)button.onclick=async()=>{const input=panel.querySelector('#certificate-name'),name=input.value.trim(),studentId=panel.querySelector('#certificate-student-id').value.trim(),status=panel.querySelector('#certificate-status');if(!name){input.setCustomValidity(say('Enter your name for the certificate.','प्रमाणपत्र के लिए अपना नाम लिखें।'));input.reportValidity();input.setCustomValidity('');return}if(!certificateEligible(scoreSummary(qs())))return;button.disabled=true;status.textContent=say('Creating PDF…','पीडीएफ बनाई जा रही है…');try{const blob=await certificatePdf(set,scores,name,studentId),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`SelfLearn-Certificate-${set.id.replace(/[^a-z0-9_-]+/gi,'-')}-${name.replace(/[^a-z0-9_-]+/gi,'-')}.pdf`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent=say('Certificate downloaded.','प्रमाणपत्र डाउनलोड हो गया।')}catch(error){status.textContent=error.message}finally{button.disabled=false}}}
 async function responsePdf(){const {PDFDocument}=await loadPdfLib(),pdf=await PDFDocument.create(),images=[];let canvas,ctx,y;const W=1240,H=1754,M=80,usable=W-M*2,newPage=()=>{if(canvas)images.push(canvas.toDataURL('image/jpeg',.72));canvas=document.createElement('canvas');canvas.width=W;canvas.height=H;ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,W,H);ctx.fillStyle='#16263a';ctx.font='bold 30px Arial, "Nirmala UI", sans-serif';ctx.fillText('SelfLearn ExamPrep',M,65);ctx.font='20px Arial, "Nirmala UI", sans-serif';ctx.fillStyle='#52657c';ctx.fillText(s.examSetId,M,100);ctx.strokeStyle='#b9cce8';ctx.beginPath();ctx.moveTo(M,120);ctx.lineTo(W-M,120);ctx.stroke();y=155},lines=(text,size,bold=false)=>{ctx.font=`${bold?'bold ':''}${size}px Arial, "Nirmala UI", sans-serif`;const out=[];for(const para of String(text??'').split(/\n/)){let line='';for(const word of (para||' ').split(/\s+/)){const next=line?line+' '+word:word;if(ctx.measureText(next).width>usable&&line){out.push(line);line=word}else line=next}out.push(line)}return out},write=(text,size=22,bold=false,color='#16263a',gap=10)=>{const ls=lines(text,size,bold),lh=Math.ceil(size*1.48);for(const line of ls){if(y+lh>H-M){newPage()}ctx.font=`${bold?'bold ':''}${size}px Arial, "Nirmala UI", sans-serif`;ctx.fillStyle=color;ctx.fillText(line,M,y);y+=lh}y+=gap};newPage();const set=examSets.find(x=>x.id===s.examSetId),list=qs(),scores=scoreSummary(list);write(lang==='hi'?(set?.titleHi||set?.title):set?.title,30,true,'#064eb2',18);write(`${lang==='hi'?'विद्यार्थी':'Student'}: ${s.name}`,23,true);write(`${lang==='hi'?'विशिष्ट आईडी':'Unique ID'}: ${s.studentId||'—'}`);write(`${lang==='hi'?'शुरू':'Started'}: ${new Date(s.startedAt).toLocaleString()}   ${lang==='hi'?'जमा':'Submitted'}: ${new Date(s.submittedAt).toLocaleString()}`);write(`${lang==='hi'?'बहुविकल्पीय अंक':'MCQ score'}: ${scores.right}/${scores.mcq.length}   ${lang==='hi'?'लिखित अस्थायी अंक':'Written provisional'}: ${scores.writtenScore}/${scores.writtenMax}`,23,true,'#145c38',8);write(`${lang==='hi'?'कुल अस्थायी अंक':'Total provisional'}: ${scores.total}/${scores.totalMax} · ${lang==='hi'?'लिखित उत्तरों की शिक्षक द्वारा जाँच आवश्यक':'Written answers need teacher review'}`,22,true,'#9a5b00',24);list.forEach((q,i)=>{if(y>H-340)newPage();write(`${i+1}. ${v(q,'question')} [${q.marks} ${lang==='hi'?'अंक':'mark'}]`,23,true,'#064eb2',8);const answer=s.answers[q.qid],option=q.type==='mcq'&&answer?v(q,'options')?.['ABCD'.indexOf(answer)]:'';write(`${lang==='hi'?'उत्तर':'Response'}: ${answer?(option?answer+'. '+option:answer):t('not')}`,22,false,'#16263a',6);if(q.type!=='mcq'){const grade=gradeWritten(q,answer);write(grade.score===null?(lang==='hi'?'स्वचालित अंक उपलब्ध नहीं · शिक्षक जाँच आवश्यक':'No automatic score · Needs teacher review'):`${lang==='hi'?'अस्थायी अंक':'Provisional score'}: ${grade.score}/${grade.max} · ${lang==='hi'?'शिक्षक जाँच आवश्यक':'Needs teacher review'}`,20,true,'#9a5b00',22)}else y+=16});images.push(canvas.toDataURL('image/jpeg',.72));for(const data of images){const image=await pdf.embedJpg(data),page=pdf.addPage([595.28,841.89]);page.drawImage(image,{x:0,y:0,width:595.28,height:841.89})}pdf.setTitle(`${s.examSetId} - ${s.name}`);pdf.setSubject('SelfLearn ExamPrep student responses and provisional scores');pdf.setCreator('SelfLearn');return new Blob([await pdf.save()],{type:'application/pdf'})}
 function deliveryStatus(kind,message){let box=document.querySelector('#delivery-status');if(!box){box=document.createElement('div');box.id='delivery-status';document.querySelector('.card').insertBefore(box,document.querySelector('.stats'))}box.className='status '+kind;box.innerHTML=`<strong>${kind==='pending'?(lang==='hi'?'ईमेल डिलीवरी लंबित':'Email delivery pending'):kind==='failed'?(lang==='hi'?'ईमेल विफल':'Email failed'):''}</strong><div>${e(message)}</div>${lastPdfBlob&&kind!=='sending'?`<button id="download-pdf" class="secondary">${lang==='hi'?'उत्तर PDF डाउनलोड करें':'Download response PDF'}</button>`:''}${kind==='pending'||kind==='failed'?`<button id="retry-email">${lang==='hi'?'PDF फिर भेजें':'Resend PDF'}</button>`:''}`;const download=document.querySelector('#download-pdf'),retry=document.querySelector('#retry-email');if(download)download.onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(lastPdfBlob);a.download=`${s.examSetId}-${(s.studentId||s.name).replace(/[^a-z0-9_-]+/gi,'-')}.pdf`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};if(retry)retry.onclick=emailResponses}
 function enhanceResultScores(){if(!s?.done||document.querySelector('#provisional-summary'))return;const list=qs(),scores=scoreSummary(list),first=document.querySelector('.card'),stats=first?.querySelector('.stats');if(!first||!stats)return;const review=scores.written.some(q=>q.type!=='numeric');stats.textContent=`${say('Objective score','वस्तुनिष्ठ अंक')}: ${scores.right}/${scores.objectiveMax}${scores.written.length?` · ${say('Other score','अन्य अंक')}: ${scores.writtenScore}/${scores.writtenMax}`:''}`;const summary=document.createElement('div');summary.id='provisional-summary';summary.className='rubric-score';summary.innerHTML=`<strong>${review?say('Total provisional score','कुल अस्थायी अंक'):say('Automatically scored','स्वचालित अंक')}: ${scores.total}/${scores.totalMax}</strong>${review?`<br><span class="review-badge">${say('Needs teacher review','शिक्षक जाँच आवश्यक')}</span> <span>${say('Written scores remain provisional until a teacher checks them.','लिखित अंक शिक्षक की जाँच तक अस्थायी हैं।')}</span>`:''}`;stats.after(summary);const cards=[...document.querySelectorAll('.card')].slice(1);list.forEach((q,i)=>{if(q.type==='mcq'||!cards[i])return;const box=document.createElement('div');box.className='rubric-score';if(objectiveTypes.has(q.type)){const earned=objectiveScore(q,s.answers[q.qid]);box.innerHTML=`<strong class="${!answered(q)?'skipped':earned===q.marks?'correct':'wrong'}">${!answered(q)?t('skipped'):earned===q.marks?t('correct'):t('wrong')} · ${earned}/${q.marks}</strong><p>${say('Answer key','उत्तर कुंजी')}: ${e(q.type==='fill'?v(q,'correct'):Array.isArray(q.correct)?q.correct.join(', '):q.correct)}</p>`}else{const grade=gradeWritten(q,s.answers[q.qid]);box.innerHTML=grade.score===null?`<span class="review-badge">${say('Needs teacher review','शिक्षक जाँच आवश्यक')}</span><p>${say('Automatic scoring is not available for this question.','इस प्रश्न के लिए स्वचालित अंक उपलब्ध नहीं हैं।')}</p>`:`<strong>${grade.needsTeacherReview?say('Provisional score','अस्थायी अंक'):say('Score','अंक')}: ${grade.score}/${grade.max}</strong>${grade.needsTeacherReview?` <span class="review-badge">${say('Needs teacher review','शिक्षक जाँच आवश्यक')}</span>`:''}${grade.matched.length?`<p class="correct">${say('Matched points','मिले हुए बिंदु')}:</p><ul>${grade.matched.map(x=>`<li>${e(x)}</li>`).join('')}</ul>`:''}${grade.missing.length?`<p class="muted">${say('Points to check','जाँचने योग्य बिंदु')}: ${e(grade.missing.join('; '))}</p>`:''}`};cards[i].appendChild(box)})}
 async function requestEmailActivation(email,status,button){button.disabled=true;status.textContent=lang==='hi'?'Activation अनुरोध भेजा जा रहा है…':'Sending activation request…';const token=`selflearn-activation-${Date.now()}`,frame=document.createElement('iframe'),form=document.createElement('form'),hidden=(name,value)=>{const input=document.createElement('input');input.type='hidden';input.name=name;input.value=value;form.appendChild(input)};frame.name=token;frame.hidden=true;form.hidden=true;form.method='POST';form.action=`https://formsubmit.co/${encodeURIComponent(email)}`;form.target=token;hidden('_subject','Activate SelfLearn ExamPrep PDF delivery');hidden('_captcha','false');hidden('_url',location.href);hidden('Message','Activate this email address to receive SelfLearn exam response PDFs.');document.body.append(frame,form);form.submit();await new Promise(resolve=>setTimeout(resolve,1500));form.remove();frame.remove();button.disabled=false;status.textContent=lang==='hi'?`${email} में FormSubmit activation ईमेल और spam फ़ोल्डर जाँचें। लिंक खोलने के बाद परीक्षा शुरू करें।`:`Check ${email} and its spam folder for the FormSubmit activation email. Open its link before starting the exam.`}
 function installActivationControl(){const fields=document.querySelector('#email-activation');if(!fields||document.querySelector('#activate-email'))return;const box=document.createElement('div');box.innerHTML=`<button type="button" id="activate-email" class="secondary">${lang==='hi'?'Activation ईमेल भेजें':'Send activation email'}</button><small class="help" id="activation-status" role="status" aria-live="polite">${lang==='hi'?'नए प्राप्तकर्ता ईमेल के लिए इसे एक बार करें।':'Do this once for each new recipient email address.'}</small>`;fields.appendChild(box);const button=box.querySelector('#activate-email');button.onclick=()=>{const input=document.querySelector('#delivery-email');if(!input.value.trim()){input.focus();box.querySelector('#activation-status').textContent=say('Enter the examiner email first.','पहले परीक्षक का ईमेल लिखें।');return;}if(!input.reportValidity())return;requestEmailActivation(input.value.trim(),box.querySelector('#activation-status'),button)}}
 function installEquationHelp(){const form=document.querySelector('#setup'),start=form?.querySelector('button:not([type="button"])');if(!form||!start||document.querySelector('#equation-help'))return;const help=document.createElement('div');help.id='equation-help';help.className='note';help.innerHTML=lang==='hi'?`<strong>समीकरण कैसे लिखें</strong><p>सामान्य कीबोर्ड अक्षर मान्य हैं। Subscript के लिए साधारण अंक, तीर के लिए <code>-&gt;</code>, बीच के बिंदु के लिए <code>.</code> और घात के लिए <code>^</code> लिखें।</p><code>4Fe + 3O2 + xH2O -&gt; 2Fe2O3.xH2O</code><p class="muted">इसे 4Fe + 3O₂ + xH₂O → 2Fe₂O₃·xH₂O के समान माना जाएगा।</p>`:`<strong>How to type equations</strong><p>Plain keyboard characters are accepted. Use ordinary numbers for subscripts, <code>-&gt;</code> for an arrow, <code>.</code> for a middle dot, and <code>^</code> for a power.</p><code>4Fe + 3O2 + xH2O -&gt; 2Fe2O3.xH2O</code><p class="muted">This is treated the same as 4Fe + 3O₂ + xH₂O → 2Fe₂O₃·xH₂O.</p>`;form.insertBefore(help,start)}
 function upgradeHomeHelp(){const form=document.querySelector('#setup'),help=document.querySelector('#equation-help'),start=form?.querySelector('button:not([type="button"])');if(!form||!help||!start||document.querySelector('#open-help'))return;const button=document.createElement('button');button.type='button';button.id='open-help';button.className='secondary help-button';button.textContent=lang==='hi'?'सहायता और निर्देश':'Help & instructions';help.className='help-dialog';help.setAttribute('role','dialog');help.setAttribute('aria-labelledby','help-title');help.innerHTML=lang==='hi'?`<div class="help-dialog-head"><h2 id="help-title">ExamPrep सहायता</h2><button type="button" class="secondary close-help" aria-label="बंद करें">बंद करें</button></div><h3>उत्तर कैसे दें</h3><ul><li>MCQ में एक विकल्प चुनें। MSQ में सभी सही विकल्प चुनें।</li><li>संख्यात्मक प्रश्न में केवल माँगा गया मान लिखें।</li><li>आपके उत्तर इसी ब्राउज़र में अपने-आप सहेजे जाते हैं।</li></ul><h3>गणितीय संकेत लिखना</h3><p><code>a_n</code> = a sub n, <code>a_n^2</code> = a sub n squared, <code>n -&gt; inf</code> = n approaches infinity.</p><h3>समीकरण कैसे लिखें</h3><p>Subscript के लिए साधारण अंक, तीर के लिए <code>-&gt;</code>, बीच के बिंदु के लिए <code>.</code> और घात के लिए <code>^</code> लिखें।</p><code>4Fe + 3O2 + xH2O -&gt; 2Fe2O3.xH2O</code><p class="muted">इसे 4Fe + 3O₂ + xH₂O → 2Fe₂O₃·xH₂O के समान माना जाएगा।</p><h3>परीक्षा के दौरान</h3><ul><li>प्रश्न सूची से किसी भी प्रश्न पर जाएँ और “पुनरावलोकन” चिह्न लगाएँ।</li><li>Listening प्रश्न में दिए गए प्रश्न-विशिष्ट audio segment बटन का उपयोग करें।</li><li>जमा करने से पहले उत्तर जाँचें। प्रकाशित परीक्षा में PDF/email निर्देश setup पर दिखेंगे।</li></ul>`:`<div class="help-dialog-head"><h2 id="help-title">ExamPrep help</h2><button type="button" class="secondary close-help" aria-label="Close help">Close</button></div><h3>How to answer</h3><ul><li>MCQ: select one option. MSQ: select every correct option.</li><li>For a numerical question, enter only the value requested unless working is requested.</li><li>Your responses are saved automatically in this browser while you work.</li></ul><h3>Typing mathematical notation</h3><p><code>a_n</code> means “a sub n”; <code>a_n^2</code> means “a sub n squared”; <code>n -&gt; inf</code> means “n approaches infinity.”</p><h3>How to type equations</h3><p>Plain keyboard characters are accepted. Use ordinary numbers for subscripts, <code>-&gt;</code> for an arrow, <code>.</code> for a middle dot, and <code>^</code> for a power.</p><code>4Fe + 3O2 + xH2O -&gt; 2Fe2O3.xH2O</code><p class="muted">This is treated the same as 4Fe + 3O₂ + xH₂O → 2Fe₂O₃·xH₂O.</p><h3>During a test</h3><ul><li>Use the question palette to move around and mark questions for review.</li><li>For listening questions, use the question-specific “Play segment” button.</li><li>Review before submitting. Published exam sets show PDF and email-delivery instructions during setup.</li></ul>`;form.insertBefore(button,help);button.onclick=()=>{help.hidden=false;document.body.classList.add('help-open');help.querySelector('.close-help').focus()};help.querySelector('.close-help').onclick=()=>{help.hidden=true;document.body.classList.remove('help-open');button.focus()};help.hidden=true}
 async function postPdfForm(blob,filename){const token=`selflearn-mail-${Date.now()}`,frame=document.createElement('iframe'),form=document.createElement('form'),hidden=(name,value)=>{const input=document.createElement('input');input.type='hidden';input.name=name;input.value=value;form.appendChild(input)};frame.name=token;frame.hidden=true;form.hidden=true;form.method='POST';form.action=`https://formsubmit.co/${encodeURIComponent(s.deliveryEmail)}`;form.enctype='multipart/form-data';form.target=token;hidden('_subject',`SelfLearn Exam — ${s.name} — ${s.studentId||'No ID'} — ${s.examSetId}`);hidden('_template','table');hidden('_captcha','false');hidden('_url',location.href);hidden('Exam set ID',s.examSetId);hidden('Student',s.name);hidden('Student unique ID',s.studentId||'Not provided');hidden('Submitted at',s.submittedAt);const attachment=document.createElement('input'),transfer=new DataTransfer();attachment.type='file';attachment.name='attachment';attachment.accept='application/pdf';transfer.items.add(new File([blob],filename,{type:'application/pdf'}));attachment.files=transfer.files;form.appendChild(attachment);document.body.append(frame,form);form.submit();await new Promise(resolve=>setTimeout(resolve,1500));form.remove();frame.remove()}
