 function enhanceActiveQuestion(){if(!s||s.done)return;const list=qs(),q=list[s.current],card=document.querySelector('.layout section.card');if(!q||!card)return;const note=document.querySelector('.note');if(note&&!note.dataset.classFixed){note.dataset.classFixed='yes';note.innerHTML=note.innerHTML.replace(lang==='hi'?'कक्षा 10':'Class 10',`${lang==='hi'?'कक्षा':'Class'} ${e(q.class||'10')}`)}if(q.imageUrl&&!card.querySelector('.pyq-diagram')){const figure=document.createElement('figure');figure.className='pyq-diagram';figure.innerHTML=`<img src="${e(q.imageUrl)}" alt="${e(lang==='hi'?'मूल प्रश्नपत्र का चित्र':'Diagram from the source paper')}">`;card.querySelector('.question').after(figure)}if(q.audioUrl&&!card.querySelector('audio')){const audio=document.createElement('div');audio.className='audio-note';audio.innerHTML=`<strong>Listening practice audio</strong>${q.modelTimestamp?` · start near ${e(q.modelTimestamp)}`:''}<audio controls preload="metadata" src="${e(q.audioUrl)}"></audio><small>${e(q.audioDisclaimer)}</small>`;card.querySelector('.question').before(audio)}if(q.type!=='msq'||card.querySelector('.msq-options'))return;const textarea=card.querySelector('#written'),label=textarea?.closest('label');if(!label)return;const selected=new Set(String(s.answers[q.qid]||''));const field=document.createElement('fieldset');field.className='msq-options';field.innerHTML=`<legend>Select all correct answers</legend><p class="msq-help">More than one option may be correct.</p>${q.options.map((x,i)=>{const letter='ABCDE'[i];return `<label class="option"><input type="checkbox" name="multi-answer" value="${letter}" ${selected.has(letter)?'checked':''}><span><strong>${letter}.</strong> ${e(x)}</span></label>`}).join('')}`;label.replaceWith(field);field.querySelectorAll('input').forEach(input=>input.onchange=()=>{s.answers[q.qid]=[...field.querySelectorAll('input:checked')].map(x=>x.value).sort().join('');if(!s.answers[q.qid])delete s.answers[q.qid];save();palette()})}
